 "content": "def transform(grid):
    """Extend each solid 3x3 colored block along its central row and column."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays = {}

    # Locate solid 3x3 monochrome blocks. The task's markers are these blocks.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[i][j] == color
                   for i in range(r, r + 3)
                   for j in range(c, c + 3)):
                center = (r + 1, c + 1)
                rays[center] = color

    # Each block projects a full-length cross. Preserve crossings between
    # different projected colors as empty cells, as in the demonstration.
    contributions = {}
    for (cr, cc), color in rays.items():
        for c in range(w):
            contributions.setdefault((cr, c), set()).add(color)
        for r in range(h):
            contributions.setdefault((r, cc), set()).add(color)

    for (r, c), colors in contributions.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
